// domains.js — page controller for site/domains.html (#169 domain-breadth gallery).
//
// Fetches data/domains.json (generated by site/domains_data.py from tasks/registry.json
// — the single source of truth; never drifts) and renders:
//   1. Live domains grouped by tier (alpha → beta → v1)
//   2. "Coming" horizon rail (dashed/muted)
//   3. Longer-horizon list
//
// All user-supplied text is set via textContent / setAttribute (no innerHTML with
// data) to avoid XSS. Treat the JSON as untrusted.

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Safe text setter — coerces null/undefined to "". */
function setText(el, v) {
  el.textContent = String(v ?? "");
}

/** Escape a string for use as an attribute value (belt-and-suspenders). */
function esc(v) {
  return String(v ?? "")
    .replace(/&/g, "&amp;")
    .replace(/"/g, "&quot;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

/** Create an element, optionally add class names, return it. */
function el(tag, ...classes) {
  const e = document.createElement(tag);
  if (classes.length) e.className = classes.filter(Boolean).join(" ");
  return e;
}

/** Produce a counts summary string like "4 scored · 1 runnable · 3 planned".
 *  Buckets with a zero count are omitted. */
function countsLine(counts) {
  if (!counts || typeof counts !== "object") return "";
  const parts = [];
  const order = [
    ["scored",   "scored"],
    ["runnable", "runnable"],
    ["alpha",    "alpha"],
    ["planned",  "planned"],
  ];
  for (const [key, label] of order) {
    const n = counts[key];
    if (typeof n === "number" && n > 0) {
      parts.push(n + " " + label);
    }
  }
  return parts.join(" · ");
}

/** Resolve a deep-link for an entry, returning { href, label } or null. */
function entryLink(entry) {
  if (entry.site_href) {
    return { href: entry.site_href, label: "View task ↗" };
  }
  if (entry.doc) {
    return {
      href: "https://github.com/tonykoop/makerbench-hwe/blob/main/" + entry.doc,
      label: "Docs ↗",
    };
  }
  if (entry.issue) {
    return {
      href: "https://github.com/tonykoop/makerbench-hwe/issues/" + entry.issue,
      label: "Issue #" + entry.issue + " ↗",
    };
  }
  return null;
}

/** Status badge label map. */
const STATUS_LABELS = {
  scored:   "live · scored",
  runnable: "runnable",
  alpha:    "alpha",
  planned:  "planned",
};

// ---------------------------------------------------------------------------
// Render helpers
// ---------------------------------------------------------------------------

/** Build a status badge <span data-status="...">. */
function buildStatusBadge(status) {
  const badge = el("span", "mb-domain-status");
  badge.setAttribute("data-status", String(status ?? "planned"));
  setText(badge, STATUS_LABELS[status] || String(status ?? ""));
  return badge;
}

/** Build a capability-axis chip <span class="mb-domain-chip">. */
function buildChip(text) {
  const chip = el("span", "mb-domain-chip");
  setText(chip, text);
  return chip;
}

/** Build an entry row inside the <details> entries list. */
function buildEntryRow(entry) {
  const row = el("li", "mb-domain-entry");

  // Title + status pill on one line
  const head = el("div", "mb-domain-entry-head");

  const titleEl = el("span", "mb-domain-entry-title");
  setText(titleEl, entry.title || entry.id);
  head.appendChild(titleEl);

  head.appendChild(buildStatusBadge(entry.status));
  row.appendChild(head);

  // Summary
  if (entry.summary) {
    const summary = el("p", "mb-domain-entry-summary");
    setText(summary, entry.summary);
    row.appendChild(summary);
  }

  // Links row
  const links = el("div", "mb-domain-entry-links");

  const mainLink = entryLink(entry);
  if (mainLink) {
    const a = el("a", "mb-domain-entry-link");
    a.setAttribute("href", esc(mainLink.href));
    a.setAttribute("rel", "noopener");
    setText(a, mainLink.label);
    links.appendChild(a);
  }

  // 3D viewer cross-link if thumbnail is set
  if (entry.thumbnail) {
    const a3d = el("a", "mb-domain-entry-link", "mb-domain-entry-link--3d");
    // Cross-link to inspect.html with deep-link hash for the entry id
    a3d.setAttribute("href", "inspect.html#" + encodeURIComponent(entry.id));
    setText(a3d, "Inspect 3D ↗");
    links.appendChild(a3d);
  }

  if (links.children.length) row.appendChild(links);

  return row;
}

/** Build a domain card element. */
function buildDomainCard(domain) {
  const card = el("div", "mb-domain-card");
  if (!domain.live) card.classList.add("mb-domain-card--not-live");

  // Card header: icon + title + status badge
  const header = el("div", "mb-domain-card-head");

  const iconEl = el("span", "mb-domain-icon");
  // icon is an emoji string — textContent is safe
  setText(iconEl, domain.icon || "");
  header.appendChild(iconEl);

  const titleEl = el("h3", "mb-domain-card-title");
  setText(titleEl, domain.title || domain.key);
  header.appendChild(titleEl);

  header.appendChild(buildStatusBadge(domain.status));
  card.appendChild(header);

  // Blurb
  if (domain.blurb) {
    const blurb = el("p", "mb-domain-blurb");
    setText(blurb, domain.blurb);
    card.appendChild(blurb);
  }

  // Counts rollup
  const cl = countsLine(domain.counts);
  if (cl) {
    const counts = el("p", "mb-domain-counts");
    setText(counts, cl);
    card.appendChild(counts);
  }

  // Capability-axis chips
  if (Array.isArray(domain.capability_axes) && domain.capability_axes.length) {
    const chips = el("div", "mb-domain-chips");
    for (const axis of domain.capability_axes) {
      chips.appendChild(buildChip(axis));
    }
    card.appendChild(chips);
  }

  // Entries expandable
  if (Array.isArray(domain.entries) && domain.entries.length) {
    const details = el("details", "mb-domain-details");
    const summary = el("summary", "mb-domain-details-summary");
    setText(summary, domain.entries.length + " task" + (domain.entries.length !== 1 ? "s" : ""));
    details.appendChild(summary);

    const list = el("ul", "mb-domain-entries");
    for (const entry of domain.entries) {
      list.appendChild(buildEntryRow(entry));
    }
    details.appendChild(list);
    card.appendChild(details);
  }

  return card;
}

/** Build a tier section: header + domain grid. */
function buildTierSection(tierMeta, domains) {
  const section = el("section", "mb-domains-tier");
  section.setAttribute("data-tier", esc(tierMeta.key));

  const heading = el("div", "mb-domains-tier-head");

  const h2 = el("h2", "mb-domains-tier-title");
  setText(h2, tierMeta.title || tierMeta.key);
  heading.appendChild(h2);

  if (tierMeta.summary) {
    const sub = el("p", "mb-domains-tier-summary");
    setText(sub, tierMeta.summary);
    heading.appendChild(sub);
  }
  section.appendChild(heading);

  const grid = el("div", "mb-domain-grid");
  for (const domain of domains) {
    grid.appendChild(buildDomainCard(domain));
  }
  section.appendChild(grid);

  return section;
}

/** Build the "Coming" horizon rail. */
function buildHorizonRail(horizonItems) {
  if (!Array.isArray(horizonItems) || !horizonItems.length) return null;

  const section = el("section", "mb-domains-tier", "mb-domains-horizon");

  const heading = el("div", "mb-domains-tier-head");
  const h2 = el("h2", "mb-domains-tier-title");
  setText(h2, "Coming next");
  heading.appendChild(h2);
  const sub = el("p", "mb-domains-tier-summary");
  setText(sub, "Domains in active development or tracked via open issues. Not yet on the leaderboard.");
  heading.appendChild(sub);
  section.appendChild(heading);

  const grid = el("div", "mb-domain-grid");

  for (const item of horizonItems) {
    const card = el("div", "mb-domain-coming");

    const head = el("div", "mb-domain-card-head");

    const iconEl = el("span", "mb-domain-icon");
    setText(iconEl, item.icon || "");
    head.appendChild(iconEl);

    const titleEl = el("h3", "mb-domain-card-title");
    setText(titleEl, item.title || item.key);
    head.appendChild(titleEl);

    // Tier label
    if (item.tier) {
      const tierBadge = el("span", "mb-domain-coming-tier");
      setText(tierBadge, item.tier);
      head.appendChild(tierBadge);
    }

    card.appendChild(head);

    if (item.blurb) {
      const blurb = el("p", "mb-domain-blurb");
      setText(blurb, item.blurb);
      card.appendChild(blurb);
    }

    if (item.issue) {
      const linkWrap = el("div", "mb-domain-entry-links");
      const a = el("a", "mb-domain-entry-link");
      a.setAttribute(
        "href",
        "https://github.com/tonykoop/makerbench-hwe/issues/" + item.issue
      );
      a.setAttribute("rel", "noopener");
      setText(a, "Issue #" + item.issue + " ↗");
      linkWrap.appendChild(a);
      card.appendChild(linkWrap);
    }

    grid.appendChild(card);
  }

  section.appendChild(grid);
  return section;
}

/** Build the longer-horizon list. */
function buildLongerHorizon(items) {
  if (!Array.isArray(items) || !items.length) return null;

  const section = el("section", "mb-domains-tier", "mb-domains-longer-horizon");

  const h2 = el("h2", "mb-domains-tier-title");
  setText(h2, "Longer horizon");
  section.appendChild(h2);

  const list = el("ul", "mb-domains-longer-list");
  for (const item of items) {
    const li = el("li");
    setText(li, item);
    list.appendChild(li);
  }
  section.appendChild(list);

  return section;
}

/** Build the provenance footnote. */
function buildProvenance(generated) {
  const note = el("p", "mb-domains-provenance");
  setText(note, "Data source: " + (generated || "tasks/registry.json — never drifts"));
  return note;
}

// ---------------------------------------------------------------------------
// Graceful empty / error state
// ---------------------------------------------------------------------------

function showError(container, message) {
  container.innerHTML = "";
  const note = el("p", "mb-domains-note", "mb-domains-error");
  setText(note, message);
  container.appendChild(note);
}

// ---------------------------------------------------------------------------
// Main render
// ---------------------------------------------------------------------------

function render(container, payload) {
  container.innerHTML = "";

  const tiers = Array.isArray(payload.tiers) ? payload.tiers : [];
  const allDomains = Array.isArray(payload.domains) ? payload.domains : [];
  const horizon = Array.isArray(payload.horizon) ? payload.horizon : [];
  const longerHorizon = Array.isArray(payload.longer_horizon) ? payload.longer_horizon : [];

  // Only show live domains in the main tier sections
  const liveDomains = allDomains.filter((d) => d.live);

  // Group live domains by tier key
  const byTier = {};
  for (const d of liveDomains) {
    const key = d.tier || "alpha";
    if (!byTier[key]) byTier[key] = [];
    byTier[key].push(d);
  }

  // Render a tier section for each tier that has live domains
  // Use the tiers[] array for ordering and metadata; fall back to inline if needed
  const tierKeys = tiers.length
    ? tiers.map((t) => t.key)
    : [...new Set(liveDomains.map((d) => d.tier || "alpha"))];

  let renderedAny = false;
  for (const key of tierKeys) {
    const domains = byTier[key];
    if (!domains || !domains.length) continue;
    const meta = tiers.find((t) => t.key === key) || { key, title: key, summary: "" };
    container.appendChild(buildTierSection(meta, domains));
    renderedAny = true;
  }

  if (!renderedAny) {
    showError(container, "No live domains found in data/domains.json.");
    return;
  }

  // Coming horizon rail
  const horizonSection = buildHorizonRail(horizon);
  if (horizonSection) container.appendChild(horizonSection);

  // Longer horizon
  const longerSection = buildLongerHorizon(longerHorizon);
  if (longerSection) container.appendChild(longerSection);

  // Provenance footnote
  container.appendChild(buildProvenance(payload._generated));
}

// ---------------------------------------------------------------------------
// Boot
// ---------------------------------------------------------------------------

document.addEventListener("DOMContentLoaded", () => {
  const container = document.getElementById("mb-domains");
  if (!container) {
    console.warn("domains.js: missing #mb-domains");
    return;
  }

  fetch("data/domains.json")
    .then((r) => {
      if (!r.ok) throw new Error("HTTP " + r.status);
      return r.json();
    })
    .then((payload) => {
      if (!payload || typeof payload !== "object") {
        showError(container, "domains.json returned an unexpected format.");
        return;
      }
      render(container, payload);
    })
    .catch((err) => {
      console.warn("domains.js: could not load data/domains.json —", err);
      showError(
        container,
        "Domain data is not available right now. " +
        "Regenerate with: python site/domains_data.py"
      );
    });
});
